<template><div class="min-h-screen"><header class="sticky top-0 z-30 border-b bg-white/95 backdrop-blur"><div class="mx-auto flex h-16 max-w-7xl items-center justify-between px-4"><RouterLink to="/shop" class="text-xl font-black">Market<span class="text-indigo-600">Flow</span></RouterLink><nav class="hidden gap-6 md:flex"><RouterLink to="/shop">Shop</RouterLink><RouterLink to="/orders">Orders</RouterLink><RouterLink to="/affiliate">Affiliate</RouterLink><RouterLink v-if="['admin','company_staff'].includes(auth.user?.role)" to="/admin">Management</RouterLink></nav><div class="flex gap-2"><RouterLink to="/cart" class="rounded-xl bg-slate-100 px-3 py-2 font-semibold">Cart {{cartCount}}</RouterLink><RouterLink v-if="!auth.user" to="/login" class="rounded-xl bg-slate-950 px-4 py-2 text-white">Sign in</RouterLink><button v-else @click="logout" class="rounded-xl border px-3 py-2">Sign out</button></div></div></header><main class="mx-auto max-w-7xl px-4 py-8"><slot/></main><footer class="mt-16 border-t bg-white p-8 text-center text-sm text-slate-500">MarketFlow · One account for commerce & affiliate marketing</footer></div></template><script>import{auth,cartCount,logout}from'../stores';export default{data(){return{auth,cartCount}},methods:{logout}}}</script>